
const $=s=>document.querySelector(s), esc=s=>String(s||'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); const itemDetailModal=$('#item-detail-modal'),featureModal=$('#feature-modal'),chatModal=$('#chat-modal'),draftModal=$('#draft-modal'),manualModal=$('#manual-modal');
let activeLocale='en',localeResources={en:{},ko:{}},localeReverse={en:new Map(),ko:new Map()},localeTemplates=[],localeTranslationScheduled=false;
function rebuildLocaleReverse(){localeTemplates=[];for(const locale of ['en','ko']){localeReverse[locale]=new Map(Object.entries(localeResources[locale]||{}).map(([key,value])=>[value,key]));for(const [key,value] of Object.entries(localeResources[locale]||{})){const names=[];const source=value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replace(/\\\{([^}]+)\\\}/g,(_,name)=>(names.push(name),'(.+?)'));if(names.length)localeTemplates.push([new RegExp('^'+source+'$'),key,names])}}}
function t(key,params={}){const template=(localeResources[activeLocale]||{})[key]||(localeResources.en||{})[key]||key;return String(template).replace(/\{(\w+)\}/g,(_,name)=>params[name]??'{'+name+'}')}
function translateValue(value){const raw=String(value||''),trimmed=raw.trim();if(!trimmed)return raw;let prefix='',lookup=trimmed;const decorated=trimmed.match(/^([✦⌕◒⚙]\s+)(.+)$/);if(decorated){prefix=decorated[1];lookup=decorated[2]}let key=localeReverse.en.get(lookup)||localeReverse.ko.get(lookup),params={};if(!key){for(const [pattern,templateKey,names] of localeTemplates){const match=lookup.match(pattern);if(match){key=templateKey;params=Object.fromEntries(names.map((name,index)=>[name,match[index+1]]));break}}}if(!key)return raw;const translated=prefix+t(key,params),start=raw.slice(0,raw.indexOf(trimmed)),end=raw.slice(raw.indexOf(trimmed)+trimmed.length);return start+translated+end}
function isUserContentNode(node){const parent=node.nodeType===Node.TEXT_NODE?node.parentElement:node;return Boolean(parent?.closest('[data-user-content],.card h3,.item-detail dd,.result h3,.result mark,.progress-comment,.solution-note p'))}
function applyLocale(root=document){if(!localeResources.en||!Object.keys(localeResources.en).length)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){if(isUserContentNode(node)||node.parentElement?.closest('script,style,textarea,option'))continue;const translated=translateValue(node.nodeValue);if(translated!==node.nodeValue)node.nodeValue=translated}for(const element of root.querySelectorAll?.('[placeholder],[aria-label],[title],[data-tooltip]')||[]){if(isUserContentNode(element))continue;for(const name of ['placeholder','aria-label','title','data-tooltip'])if(element.hasAttribute(name)){const value=element.getAttribute(name),translated=translateValue(value);if(value!==translated)element.setAttribute(name,translated)}}if(document.documentElement.lang!==activeLocale)document.documentElement.lang=activeLocale;const title=t('app.document_title');if(document.title!==title)document.title=title;const select=$('#locale-select');if(select&&select.value!==activeLocale)select.value=activeLocale}
function scheduleLocaleApply(){if(localeTranslationScheduled)return;localeTranslationScheduled=true;queueMicrotask(()=>{localeTranslationScheduled=false;applyLocale()})}
const localeObserver=new MutationObserver(scheduleLocaleApply);localeObserver.observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title','data-tooltip']});
const applicationRequest=(path,options={})=>window.llmWikiApplication.request({path,...options});
async function applicationEvents(path,eventName,onEvent,signal){while(!signal?.aborted){try{const response=await applicationRequest(path,{headers:{Accept:'text/event-stream'},signal});if(!response.ok||!response.body)throw Error(await response.text());const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',activeEvent='message';for(;;){const next=await reader.read();if(next.done)break;buffer+=decoder.decode(next.value,{stream:true});const lines=buffer.split('\n');buffer=lines.pop()||'';for(const raw of lines){const line=raw.replace(/\r$/,'');if(line.startsWith('event:'))activeEvent=line.slice(6).trim();else if(!line){if(activeEvent===eventName)onEvent();activeEvent='message'}}}if(signal?.aborted)return}catch(error){if(signal?.aborted||error?.name==='AbortError')return}await new Promise(resolve=>setTimeout(resolve,1000))}}
async function initializeLocale(){try{const browserLocale=navigator.language||'en',setting=await applicationRequest('/settings/locale?browser_locale='+encodeURIComponent(browserLocale),{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject());const [en,ko]=await Promise.all(['en','ko'].map(locale=>applicationRequest('/i18n/'+locale,{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject())));localeResources={en,ko};rebuildLocaleReverse();activeLocale=setting.locale==='ko'?'ko':'en';applyLocale();await Promise.all([loadBoard(),loadDashboard()]);return setting}catch(_error){activeLocale='en';document.documentElement.lang='en';await Promise.allSettled([loadBoard(),loadDashboard()]);return null}}
async function setLocale(locale,persist=true){const previousLocale=activeLocale;activeLocale=locale==='ko'?'ko':'en';applyLocale();if(persist){try{const saved=await api('/settings/locale',{method:'PUT',body:JSON.stringify({locale:activeLocale})});activeLocale=saved.locale==='ko'?'ko':'en';applyLocale();await loadBoard();await loadDashboard();if(window.openKnowledgePath&&itemDetailModal.open)await searchArchivedDocument(window.openKnowledgePath);if(chatTarget?.type==='features'&&chatModal.open){if(chatTarget.mode==='completed'){const progress=await api('/features/'+chatTarget.id+'/progress'),solution=window.completedSolutions?.[chatTarget.id]||{};$('#explore-preview-work').innerHTML=readonlyProgressMarkup(solution,progress)}else await renderExploreWork(chatTarget.id)}}catch(error){activeLocale=previousLocale;applyLocale();showNotice(error.message,t('common.something_needs_attention'))}}}
$('#locale-select').onchange=event=>setLocale(event.target.value);
const refinementPreviewFailureMessage='Refinement preview is unavailable. Please try again.';let activeRefinementPreview=null,refinementPreviewDraft=null,previewActiveTab='context';chatModal.querySelector('.modal').insertAdjacentHTML('afterbegin','<button type="button" id="refinement-preview-warning" class="tiny icon-action" hidden aria-label="'+refinementPreviewFailureMessage+'" data-tooltip="'+refinementPreviewFailureMessage+'">!</button>');chatModal.querySelector('#chat-form footer button').onclick=closeRefinementModal;chatModal.addEventListener('cancel',()=>{supersedeRefinementPreview();clearRefinementPreviewWarning()});
function clearRefinementPreviewWarning(){$('#refinement-preview-warning').hidden=true}function showRefinementPreviewWarning(){$('#refinement-preview-warning').hidden=false}function supersedeRefinementPreview(){const attempt=activeRefinementPreview;if(attempt){attempt.cancelled=true;attempt.controller.abort();attempt.generationCard?.remove()}activeRefinementPreview=null}function closeRefinementModal(){supersedeRefinementPreview();clearRefinementPreviewWarning();chatModal.close()}
async function api(path,options={}){const headers={'Content-Type':'application/json','X-LLM-Wiki-Locale':activeLocale,...(options.headers||{})},r=await applicationRequest(path,{...options,headers});if(!r.ok)throw Error(await r.text());return r.status===204?null:r.json()}
